/// <summary>
/// designed from AVA
/// </summary>
protected void initFormLetterReport()
{
    super();

    SRSPrintDestinationSettings     archivePrintDestinationSettings = new SRSPrintDestinationSettings();

    archivePrintDestinationSettings.printMediumType(SRSPrintMediumType::Archive);
    formLetterReport.parmDefaultOriginalPrintJobSettings(archivePrintDestinationSettings);
    formLetterReport.parmUsePrintMgmtDestinations(true);

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args _args)
{
    AVASalesQuotationController_PrintArchive salesQuotationController_PrintArchive = AVASalesQuotationController_PrintArchive::construct();

    salesQuotationController_PrintArchive.initArgs(_args, PrintMgmtDocType::construct(PrintMgmtDocumentType::Quotation).getDefaultReportFormat());

    salesQuotationController_PrintArchive.startOperation();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>AVASalesQuotationController_PrintArchive</returns>
public static AVASalesQuotationController_PrintArchive construct()
{
    return new AVASalesQuotationController_PrintArchive();
}
